-- 0005_payments.sql
-- Stage 8: payment persistence and wallet crediting (prepared, NOT applied).
--
-- This migration records payment attempts, stores provider events for replay
-- protection, and credits the QuickBiz wallet exactly once per successful payment.
-- It depends on 0004_wallet.sql (wallets, wallet_entries, wallet_credit).
--
-- Design notes:
--   * `payments.reference` is our own id, generated by the API before the
--     provider is called; the provider echoes it back.
--   * `payment_events.provider_event_id` is unique per provider, so a redelivered
--     webhook is a no-op instead of a second credit. On duplicate event IDs, the
--     existing event is compared with the incoming event; conflicts are rejected.
--   * Crediting is idempotent: the ledger entry id is derived from the payment
--     reference, so replaying the credit cannot double-pay.
--   * External refunds (payment_refund) record the provider-confirmed refund
--     (reference + amount) on the payment row and mark it 'refunded' but do NOT
--     credit the QuickBiz wallet. The Worker must obtain provider confirmation
--     BEFORE calling payment_refund.
--   * Internal wallet compensation (payment_compensate) credits the wallet once
--     via a deterministic 'comp:<reference>' ledger entry, for cases where
--     QuickBiz owes the customer wallet credit without an external provider
--     refund.
--   * A payment can be externally refunded OR internally compensated, never both.
--     payment_refund and payment_compensate lock the same payment row FOR UPDATE
--     and check the other's marker, so concurrent calls serialise and double
--     benefit is impossible.
--   * Partial refunds and partial compensation are NOT supported (full amount
--     only). This limitation is explicit.
--   * Only the service role (the Worker) may write these tables.
--
-- APPLY THIS ONLY AFTER OWNER APPROVAL. Nothing in the build applies it.

-- ---------------------------------------------------------------------------
-- UUID function dependency note
-- ---------------------------------------------------------------------------
-- The tables below use `gen_random_uuid()` as a default for UUID columns.
-- The schema containing this function must be verified against the live database
-- before applying this migration. Run the following read-only queries to confirm:
--
--   SELECT n.nspname FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
--   WHERE p.proname = 'gen_random_uuid';
--
-- If the function lives in `extensions` (pgcrypto installed there), the default
-- is valid as-written. If it lives in `pg_catalog`, change defaults to
-- `DEFAULT pg_catalog.gen_random_uuid()`. If in `public` and `public` is in
-- search_path, the unqualified name works. If not found, pgcrypto must be
-- installed or the `extensions` schema added to search_path before table creation.
-- DO NOT GUESS. Verify before applying.

-- ---------------------------------------------------------------------------
-- Payments
-- ---------------------------------------------------------------------------

create table if not exists public.payments (
  reference text primary key,
  user_id uuid not null references auth.users (id) on delete cascade,
  provider text not null,
  amount_minor bigint not null check (amount_minor > 0),
  currency text not null check (currency ~ '^[A-Z]{3}$'),
  status text not null default 'pending'
    check (status in ('pending', 'success', 'failed', 'abandoned', 'refunded')),
  provider_reference text,
  authorization_url text,
  paid_at timestamptz,
  refunded_at timestamptz,
  refund_reference text,
  refund_amount_minor bigint,
  compensation_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

comment on table public.payments is
  'One row per checkout attempt. Balances are never accepted from the browser; only the provider response, re-verified server-side, may change status. paid_at records settlement time; refunded_at/refund_reference record a provider-confirmed external refund; compensation_at records an internal wallet compensation. A payment can be externally refunded OR internally compensated, never both.';

create index if not exists payments_user_created_idx on public.payments (user_id, created_at desc);
create index if not exists payments_status_idx on public.payments (status);

alter table public.payments enable row level security;

drop policy if exists "payments_select_own" on public.payments;
create policy "payments_select_own"
  on public.payments
  for select
  to authenticated
  using ((select auth.uid()) = user_id);

-- No client insert/update/delete: the Worker writes these as service_role.
revoke all on public.payments from public, anon, authenticated;
grant select on public.payments to authenticated;

drop trigger if exists payments_touch_updated_at on public.payments;
create trigger payments_touch_updated_at
  before update on public.payments
  for each row execute function public.touch_updated_at();

-- ---------------------------------------------------------------------------
-- Provider events (replay protection with conflict detection)
-- ---------------------------------------------------------------------------

create table if not exists public.payment_events (
  id uuid primary key default gen_random_uuid(),
  provider text not null,
  provider_event_id text not null,
  type text not null,
  reference text,
  status text,
  payload jsonb,
  received_at timestamptz not null default now(),
  constraint payment_events_unique_event unique (provider, provider_event_id)
);

comment on table public.payment_events is
  'Every verified provider event. The unique (provider, provider_event_id) constraint rejects redelivered webhooks. On duplicate event IDs, the existing event is compared with the incoming event; conflicts are rejected.';

alter table public.payment_events enable row level security;
-- No policies at all: only the service role can read or write provider events.

revoke all on public.payment_events from public, anon, authenticated;

-- ---------------------------------------------------------------------------
-- Service-role functions
-- ---------------------------------------------------------------------------

-- Record or update a checkout attempt. Safe to call twice with the same reference.
-- If the reference already exists, ALL important fields are verified. Mismatches
-- are rejected instead of silently ignored.
create or replace function public.payment_record_attempt(
  p_reference text,
  p_user_id uuid,
  p_provider text,
  p_amount_minor bigint,
  p_currency text,
  p_authorization_url text default null
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_existing_user_id uuid;
  v_existing_provider text;
  v_existing_amount bigint;
  v_existing_currency text;
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'forbidden' using errcode = 'insufficient_privilege';
  end if;

  insert into public.payments (reference, user_id, provider, amount_minor, currency, authorization_url)
  values (p_reference, p_user_id, p_provider, p_amount_minor, p_currency, p_authorization_url)
  on conflict (reference) do update set
    updated_at = now()
  where public.payments.user_id = p_user_id
    and public.payments.provider = p_provider
    and public.payments.amount_minor = p_amount_minor
    and public.payments.currency = p_currency
  returning 1;

  if not found then
    -- Conflict row exists but parameters do not match.
    select user_id, provider, amount_minor, currency
    into v_existing_user_id, v_existing_provider, v_existing_amount, v_existing_currency
    from public.payments
    where reference = p_reference;

    raise exception
      'payment reference conflict: existing payment % has user_id=%, provider=%, amount_minor=%, currency=%; requested user_id=%, provider=%, amount_minor=%, currency=%',
      p_reference, v_existing_user_id, v_existing_provider, v_existing_amount, v_existing_currency,
      p_user_id, p_provider, p_amount_minor, p_currency
      using errcode = 'check_violation';
  end if;
end;
$$;

-- Store a verified provider event. A redelivery with the same event id is a no-op.
-- On duplicate (provider, provider_event_id), the existing event is compared with
-- the incoming event. Matching retries return false (safe no-op). Conflicts
-- (different type, reference, status, or payload) raise an exception.
-- Webhook signature verification is performed in the Worker before calling this
-- function; it is not part of this SQL.
create or replace function public.payment_store_event(
  p_provider text,
  p_provider_event_id text,
  p_type text,
  p_reference text,
  p_status text,
  p_payload jsonb
)
returns boolean
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_inserted boolean;
  v_existing_type text;
  v_existing_reference text;
  v_existing_status text;
  v_existing_payload jsonb;
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'forbidden' using errcode = 'insufficient_privilege';
  end if;

  insert into public.payment_events (provider, provider_event_id, type, reference, status, payload)
  values (p_provider, p_provider_event_id, p_type, p_reference, p_status, p_payload)
  on conflict (provider, provider_event_id) do nothing;

  v_inserted := found;

  if not v_inserted then
    -- Duplicate event ID. Compare existing event with incoming event.
    select type, reference, status, payload
    into v_existing_type, v_existing_reference, v_existing_status, v_existing_payload
    from public.payment_events
    where provider = p_provider and provider_event_id = p_provider_event_id;

    if v_existing_type is distinct from p_type
       or v_existing_reference is distinct from p_reference
       or v_existing_status is distinct from p_status
       or v_existing_payload is distinct from p_payload then
      raise exception
        'payment event conflict: provider event id % reused with conflicting parameters (type=%, reference=%, status=%)',
        p_provider_event_id, v_existing_type, v_existing_reference, v_existing_status
        using errcode = 'check_violation';
    end if;

    -- Matching retry: safe no-op.
    return false;
  end if;

  return true;
end;
$$;

-- Mark a payment successful and credit the QuickBiz wallet exactly once.
--
-- Concurrency safety:
--   1. SELECT ... FOR UPDATE on the payment row serializes concurrent settlement
--      attempts for the same reference.
--   2. Only status = 'pending' payments can be settled; failed/abandoned/refunded
--      payments are rejected.
--   3. If status = 'success' (already settled), the matching wallet ledger entry
--      ('payment:' || reference) is verified. The verification checks:
--        - ledger entry ID matches 'payment:' || reference
--        - ledger entry wallet_id matches the payment's user wallet
--        - ledger entry kind = 'credit'
--        - ledger entry amount_minor matches payment amount_minor
--        - ledger entry currency matches payment currency
--        - ledger entry reference matches payment reference
--      If found and consistent, returns safely without another credit.
--      If missing or inconsistent, raises a settlement-inconsistency exception.
--   4. Wallet currency is checked against payment currency; mismatches are rejected.
--   5. Ledger entry id 'payment:' || reference is idempotent in wallet_insert_entry.
--   6. Wallet creation uses INSERT ... ON CONFLICT (user_id) DO NOTHING to handle
--      concurrent wallet creation for the same user inside the database.
--   7. All steps (lock, validate, currency check, create wallet, credit, update
--      status) run in one PL/pgSQL transaction: atomic.
--
-- LIMITATION: This function credits the QuickBiz wallet. It does NOT communicate
-- with the payment provider. The Worker must verify provider signature and
-- payment amount/currency/reference BEFORE calling this function.
create or replace function public.payment_settle(
  p_reference text,
  p_paid_at timestamptz default now()
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_payment public.payments;
  v_wallet_id uuid;
  v_wallet_currency text;
  v_ledger_id text;
  v_ledger_wallet_id uuid;
  v_ledger_kind text;
  v_ledger_amount bigint;
  v_ledger_currency text;
  v_ledger_reference text;
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'forbidden' using errcode = 'insufficient_privilege';
  end if;

  -- Lock the payment row to serialize concurrent settlements.
  select * into v_payment
  from public.payments
  where reference = p_reference
  for update;

  if v_payment.reference is null then
    raise exception 'unknown payment' using errcode = 'no_data_found';
  end if;

  -- Already settled: verify matching wallet ledger entry exists and is consistent.
  if v_payment.status = 'success' then
    select we.id, we.wallet_id, we.kind, we.amount_minor, we.currency, we.reference
    into v_ledger_id, v_ledger_wallet_id, v_ledger_kind, v_ledger_amount, v_ledger_currency, v_ledger_reference
    from public.wallet_entries we
    where we.id = 'payment:' || v_payment.reference;

    if v_ledger_id is null then
      raise exception
        'settlement inconsistency: payment % marked success but no matching wallet ledger entry',
        p_reference
        using errcode = 'check_violation';
    end if;

    -- Verify all ledger fields match the payment.
    select id into v_wallet_id
    from public.wallets
    where user_id = v_payment.user_id;

    if v_ledger_wallet_id is distinct from v_wallet_id
       or v_ledger_kind is distinct from 'credit'
       or v_ledger_amount is distinct from v_payment.amount_minor
       or v_ledger_currency is distinct from v_payment.currency
       or v_ledger_reference is distinct from v_payment.reference then
      raise exception
        'settlement inconsistency: payment % ledger credit does not match payment wallet/kind/amount/currency/reference',
        p_reference
        using errcode = 'check_violation';
    end if;

    return;
  end if;

  -- Only pending payments can be settled. Failed/abandoned/refunded are rejected.
  if v_payment.status <> 'pending' then
    raise exception
      'payment % is not pending (current status: %)',
      p_reference, v_payment.status
      using errcode = 'check_violation';
  end if;

  -- Find or create the user's wallet atomically (handles concurrent creation).
  select id into v_wallet_id
  from public.wallets
  where user_id = v_payment.user_id;

  if v_wallet_id is null then
    insert into public.wallets (user_id, currency)
    values (v_payment.user_id, v_payment.currency)
    on conflict (user_id) do nothing
    returning id into v_wallet_id;
  end if;

  if v_wallet_id is null then
    select id into v_wallet_id
    from public.wallets
    where user_id = v_payment.user_id;
  end if;

  -- Currency check: existing wallet currency must match payment currency.
  select currency into v_wallet_currency
  from public.wallets
  where id = v_wallet_id;

  if v_wallet_currency <> v_payment.currency then
    raise exception
      'currency mismatch: wallet holds %, payment is %',
      v_wallet_currency, v_payment.currency
      using errcode = 'check_violation';
  end if;

  -- Credit the QuickBiz wallet. The ledger entry id is derived from the payment
  -- reference, and wallet_insert_entry ignores a duplicate id, so this is safe
  -- to retry. This does NOT trigger an external refund or payout.
  perform public.wallet_credit(
    v_wallet_id,
    'payment:' || v_payment.reference,
    v_payment.amount_minor,
    v_payment.currency,
    v_payment.reference
  );

  update public.payments
  set status = 'success', paid_at = coalesce(p_paid_at, now())
  where reference = p_reference;
end;
$$;

-- Mark a payment failed (no money moves). Idempotent: only pending → failed.
create or replace function public.payment_fail(p_reference text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_exists boolean;
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'forbidden' using errcode = 'insufficient_privilege';
  end if;

  update public.payments
  set status = 'failed'
  where reference = p_reference and status = 'pending';

  if not found then
    select exists (select 1 from public.payments where reference = p_reference) into v_exists;
    if not v_exists then
      raise exception 'unknown payment' using errcode = 'no_data_found';
    else
      raise exception 'payment % is not pending' using errcode = 'check_violation';
    end if;
  end if;
end;
$$;

-- Mark a successful payment as externally refunded.
--
-- External refund separation:
--   1. Already-refunded returns successfully BEFORE any other status checks.
--   2. Only status = 'success' payments can be externally refunded;
--      pending/failed/abandoned payments are rejected.
--   3. A payment already internally compensated (compensation_at set) is rejected,
--      so the same payment cannot benefit from BOTH an external refund and an
--      internal wallet compensation.
--   4. Full-refund-only: the provider-confirmed refund amount must equal the
--      captured amount.
--   5. This function does NOT credit the QuickBiz wallet. It records the
--      provider-confirmed refund (reference + amount) and marks the payment
--      'refunded'. The row lock serialises concurrent refund/compensation calls.
--
-- CRITICAL: This function does NOT trigger an external refund. The Worker must
-- obtain provider confirmation (signature/amount/currency/reference) and pass the
-- provider's refund id and confirmed amount BEFORE calling this function. A DB
-- status update alone is not an external refund.
--
-- LIMITATION: Full refund only. Partial external refunds are not supported.
create or replace function public.payment_refund(
  p_reference text,
  p_refund_reference text,
  p_refund_amount_minor bigint,
  p_refund_at timestamptz default now()
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_payment public.payments;
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'forbidden' using errcode = 'insufficient_privilege';
  end if;

  -- Lock the payment row first to serialize concurrent refund/compensation calls.
  select * into v_payment
  from public.payments
  where reference = p_reference
  for update;

  if v_payment.reference is null then
    raise exception 'unknown payment' using errcode = 'no_data_found';
  end if;

  -- Already refunded: return successfully before any other status checks.
  if v_payment.status = 'refunded' then
    return;
  end if;

  -- A payment already compensated internally cannot also be externally refunded.
  if v_payment.compensation_at is not null then
    raise exception
      'payment % already internally compensated; external refund refused',
      p_reference
      using errcode = 'check_violation';
  end if;

  -- Only successful payments can be externally refunded.
  if v_payment.status <> 'success' then
    raise exception
      'payment % is not successful (current status: %)',
      p_reference, v_payment.status
      using errcode = 'check_violation';
  end if;

  -- Full-refund-only: the provider-confirmed amount must equal the captured amount.
  if p_refund_amount_minor is distinct from v_payment.amount_minor then
    raise exception
      'refund amount % does not equal captured amount % for payment %',
      p_refund_amount_minor, v_payment.amount_minor, p_reference
      using errcode = 'check_violation';
  end if;

  -- Record the provider-confirmed external refund. Does NOT credit the wallet.
  update public.payments
  set status = 'refunded',
      refunded_at = coalesce(p_refund_at, now()),
      refund_reference = p_refund_reference,
      refund_amount_minor = p_refund_amount_minor
  where reference = p_reference;
end;
$$;

-- Internal wallet compensation for a specific payment.
--
-- This is the ONLY path that credits the wallet for compensation, and it is tied
-- to a payment so the same payment cannot be both externally refunded and
-- internally compensated:
--   * locks the payment row FOR UPDATE (same lock as payment_refund) so a
--     concurrent refund and compensation serialise;
--   * rejects a payment already externally refunded (status='refunded') or already
--     compensated (compensation_at set);
--   * requires status='success';
--   * credits the wallet via wallet_compensate with a deterministic ledger id
--     'comp:<reference>' (the ledger PK guarantees one compensation per payment);
--   * sets compensation_at for audit.
--
-- LIMITATION: Full amount only. Partial compensation is not supported.
create or replace function public.payment_compensate(
  p_reference text,
  p_description text default ''
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_payment public.payments;
  v_wallet_id uuid;
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'forbidden' using errcode = 'insufficient_privilege';
  end if;

  -- Lock the payment row first (same lock order as payment_refund).
  select * into v_payment
  from public.payments
  where reference = p_reference
  for update;

  if v_payment.reference is null then
    raise exception 'unknown payment' using errcode = 'no_data_found';
  end if;

  -- Already compensated: idempotent no-op.
  if v_payment.compensation_at is not null then
    return;
  end if;

  -- A payment already externally refunded cannot also be compensated.
  if v_payment.status = 'refunded' then
    raise exception
      'payment % already externally refunded; compensation refused',
      p_reference
      using errcode = 'check_violation';
  end if;

  if v_payment.status <> 'success' then
    raise exception
      'payment % is not successful (current status: %)',
      p_reference, v_payment.status
      using errcode = 'check_violation';
  end if;

  -- Find or create the user's wallet (same pattern as payment_settle).
  select id into v_wallet_id
  from public.wallets
  where user_id = v_payment.user_id;

  if v_wallet_id is null then
    insert into public.wallets (user_id, currency)
    values (v_payment.user_id, v_payment.currency)
    on conflict (user_id) do nothing
    returning id into v_wallet_id;
  end if;

  if v_wallet_id is null then
    select id into v_wallet_id
    from public.wallets
    where user_id = v_payment.user_id;
  end if;

  -- Credit the wallet via the internal compensation path (distinct kind/reference).
  perform public.wallet_compensate(
    v_wallet_id,
    'comp:' || v_payment.reference,
    v_payment.amount_minor,
    v_payment.currency,
    v_payment.reference,
    p_description
  );

  update public.payments
  set compensation_at = now()
  where reference = p_reference;
end;
$$;

-- ---------------------------------------------------------------------------
-- Reconciliation view (service_role access only)
-- ---------------------------------------------------------------------------

-- A successful payment whose ledger credit is missing. Should always be empty;
-- any row indicates a settlement failure between payment update and ledger credit.
create or replace view public.payment_reconciliation as
select
  p.reference,
  p.user_id,
  p.amount_minor,
  p.currency,
  p.paid_at
from public.payments p
left join public.wallet_entries e
  on e.id = 'payment:' || p.reference
where p.status = 'success'
  and e.id is null;

comment on view public.payment_reconciliation is
  'Successful payments with no matching ledger credit. Any row is an alert. Access restricted to service_role.';

-- ---------------------------------------------------------------------------
-- Function grants
-- ---------------------------------------------------------------------------

revoke all on function public.payment_record_attempt(text, uuid, text, bigint, text, text)
  from public, anon, authenticated;
revoke all on function public.payment_store_event(text, text, text, text, text, jsonb)
  from public, anon, authenticated;
revoke all on function public.payment_settle(text, timestamptz)
  from public, anon, authenticated;
revoke all on function public.payment_fail(text)
  from public, anon, authenticated;
revoke all on function public.payment_refund(text, text, bigint, timestamptz)
  from public, anon, authenticated;
revoke all on function public.payment_compensate(text, text)
  from public, anon, authenticated;

grant execute on function public.payment_record_attempt(text, uuid, text, bigint, text, text) to service_role;
grant execute on function public.payment_store_event(text, text, text, text, text, jsonb) to service_role;
grant execute on function public.payment_settle(text, timestamptz) to service_role;
grant execute on function public.payment_fail(text) to service_role;
grant execute on function public.payment_refund(text, text, bigint, timestamptz) to service_role;
grant execute on function public.payment_compensate(text, text) to service_role;

-- Reconciliation view: service_role only. No client access.
revoke all on public.payment_reconciliation from public, anon, authenticated;
grant select on public.payment_reconciliation to service_role;